        const SafeStorage = {
            mem: {},
            getItem(k) {
                try { return localStorage.getItem(k); } catch (e) { return this.mem[k] || null; }
            },
            setItem(k, v) {
                try { localStorage.setItem(k, v); } catch (e) { this.mem[k] = String(v); }
            },
            removeItem(k) {
                try { localStorage.removeItem(k); } catch (e) { delete this.mem[k]; }
            },
            getSession(k) {
                try { return sessionStorage.getItem(k); } catch (e) { return this.mem['s_' + k] || null; }
            },
            setSession(k, v) {
                try { sessionStorage.setItem(k, v); } catch (e) { this.mem['s_' + k] = String(v); }
            },
            removeSession(k) {
                try { sessionStorage.removeItem(k); } catch (e) { delete this.mem['s_' + k]; }
            }
        };

