            init: async function() {
                await this.loadDatabase();
                this.applyLogoBranding();

                const savedUser = SafeStorage.getSession('pashusevaUser');
                if (savedUser) {
                    try {
                        this.currentUser = JSON.parse(savedUser);
                        this.auth.showApp();
                    } catch (e) {}
                }

                const loginForm = document.getElementById('login-form');
                if (loginForm) {
                    loginForm.addEventListener('submit', (e) => {
                        e.preventDefault();
                        this.auth.login();
                    });
                }

                window.addEventListener('hashchange', () => this.router.navigate());
                this.sidebar.initGestures();
            },

            sidebar: {
                isOpen: false,
                hideTimer: null,
                touchStartX: 0,
                touchStartY: 0,

                open: function() {
                    this.cancelAutoHide();
                    const sb = document.getElementById('app-sidebar');
                    const bd = document.getElementById('sidebar-backdrop');
                    if (sb) sb.classList.add('sidebar-open');
                    if (bd) bd.classList.remove('hidden');
                    this.isOpen = true;
                },

                close: function() {
                    this.cancelAutoHide();
                    const sb = document.getElementById('app-sidebar');
                    const bd = document.getElementById('sidebar-backdrop');
                    if (sb) sb.classList.remove('sidebar-open');
                    if (bd) bd.classList.add('hidden');
                    this.isOpen = false;
                },

                toggle: function() {
                    if (this.isOpen) {
                        this.close();
                    } else {
                        this.open();
                    }
                },

                openOnHover: function() {
                    if (window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
                        this.open();
                    }
                },

                cancelAutoHide: function() {
                    if (this.hideTimer) {
                        clearTimeout(this.hideTimer);
                        this.hideTimer = null;
                    }
                },

                scheduleAutoHide: function() {
                    this.cancelAutoHide();
                    if (window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
                        this.hideTimer = setTimeout(() => {
                            this.close();
                        }, 260);
                    }
                },

                onNavClick: function(targetHash) {
                    this.close();
                    if (window.location.hash === '#' + targetHash) {
                        app.router.navigate();
                    }
                },

                initGestures: function() {
                    document.addEventListener('keydown', (e) => {
                        if (e.key === 'Escape') {
                            if (app.state.modalStack.length > 0) {
                                app.modals.closeTop();
                            } else if (this.isOpen) {
                                this.close();
                            }
                        }
                    });

                    document.addEventListener('touchstart', (e) => {
                        if (!e.touches || e.touches.length !== 1) return;
                        this.touchStartX = e.touches[0].clientX;
                        this.touchStartY = e.touches[0].clientY;
                    }, { passive: true });

                    document.addEventListener('touchend', (e) => {
                        if (!e.changedTouches || e.changedTouches.length !== 1) return;
                        const dx = e.changedTouches[0].clientX - this.touchStartX;
                        const dy = Math.abs(e.changedTouches[0].clientY - this.touchStartY);
                        if (dy > 60) return;
                        // Swipe right from left edge opens sidebar
                        if (!this.isOpen && this.touchStartX < 28 && dx > 55 && app.currentUser) {
                            this.open();
                        } else if (this.isOpen && dx < -55) {
                            // Swipe left closes sidebar
                            this.close();
                        }
                    }, { passive: true });
                }
            },

            loadDatabase: async function() {
                const localRaw = SafeStorage.getItem('MMPSK_DB_V2');
                if (localRaw) {
                    try { this.db = JSON.parse(localRaw); } catch (e) { this.db = getInitialSeedDatabase(); }
                } else {
                    this.db = getInitialSeedDatabase();
                    SafeStorage.setItem('MMPSK_DB_V2', JSON.stringify(this.db));
                }

                // Attempt connection to Node.js + Express backend if running on localhost/server
                if (window.location.protocol.startsWith('http')) {
                    try {
                        const res = await fetch(window.location.origin + '/api/state');
                        if (res.ok) {
                            const json = await res.json();
                            this.serverOnline = true;
                            if (json.data && json.data.products) {
                                this.db = json.data;
                                SafeStorage.setItem('MMPSK_DB_V2', JSON.stringify(this.db));
                            } else {
                                await this.saveDatabase(true);
                            }
                            this.updateSyncBadge(true);
                        }
                    } catch (e) {
                        this.serverOnline = false;
                        this.updateSyncBadge(false);
                    }
                }
                this.refreshDatalists();
            },

            saveDatabase: async function(silent = false) {
                this.db.lastUpdated = new Date().toISOString();
                SafeStorage.setItem('MMPSK_DB_V2', JSON.stringify(this.db));
                this.refreshDatalists();

                if (this.serverOnline) {
                    try {
                        await fetch(window.location.origin + '/api/state', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(this.db)
                        });
                    } catch (e) {}
                }
                if (!silent) {
                    const dot = document.getElementById('sync-dot');
                    if (dot) {
                        dot.classList.add('scale-125');
                        setTimeout(() => dot.classList.remove('scale-125'), 300);
                    }
                }
            },

            updateSyncBadge: function(online) {
                const lbl = document.getElementById('sync-status-label');
                if (lbl) lbl.innerText = online ? 'Server + SQLite Sync' : 'Local + Auto-Backup';
            },

            refreshDatalists: function() {
                const dlMed = document.getElementById('dl-medicines');
                if (dlMed) {
                    dlMed.innerHTML = this.db.products.map(p => {
                        const totalQty = this.items.getTotalStock(p.id);
                        return `<option value="${p.name}">${p.brand || 'Vet'} | HSN:${p.hsn} | GST:${p.gstRate}% | Stock:${totalQty} ${p.unit}</option>`;
                    }).join('');
                }
                const dlCust = document.getElementById('dl-customers');
                if (dlCust) {
                    dlCust.innerHTML = this.db.parties.filter(p => p.partyType === 'Customer').map(p =>
                        `<option value="${p.name}">${p.phone} | Due: ₹${Number(p.currentBalance).toFixed(2)}</option>`
                    ).join('');
                }
                const dlSup = document.getElementById('dl-suppliers');
                if (dlSup) {
                    dlSup.innerHTML = this.db.parties.filter(p => p.partyType === 'Supplier').map(p =>
                        `<option value="${p.name}">${p.phone} | Payable: ₹${Number(p.currentBalance).toFixed(2)}</option>`
                    ).join('');
                }
            },

