                    document.getElementById('dash-sales-count').innerText = `${app.db.sales.length} Retail Invoices`;
                    document.getElementById('dash-total-purchases').innerText = `₹ ${totalPur.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`;
                    document.getElementById('dash-purchases-count').innerText = `${app.db.purchases.length} Supplier Bills`;
                    document.getElementById('dash-receivables').innerText = `₹ ${totalReceivables.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`;
                    document.getElementById('dash-expiry-count').innerText = `${expiryBatches.length} Batches`;

